def nbbo_spread(bid, ask, tick=0.01):
    if bid >= ask:
        raise ValueError('locked or crossed book')
    spread = round(ask - bid, 4)
    mid = round((bid + ask) / 2, 4)
    return {'spread': spread, 'ticks': round(spread / tick), 'mid': mid, 'spread_bps': round(spread / mid * 10000, 2)}

import math


def snap_to_tick(price, tick, side):
    if side == 'BUY':
        steps = math.floor(price / tick + 1e-9)
    else:
        steps = math.ceil(price / tick - 1e-9)
    return round(steps * tick, 4)

def insert_order(book, order):
    if order['side'] == 'BUY':
        side, worse = book['bids'], lambda resting: resting['price'] < order['price']
    else:
        side, worse = book['asks'], lambda resting: resting['price'] > order['price']
    pos = len(side)
    for i, resting in enumerate(side):
        if worse(resting):
            pos = i
            break
    side.insert(pos, order)
    return book

def cumulative_depth(levels, n):
    out, total = [], 0
    for price, qty in levels[:n]:
        total += qty
        out.append((price, total))
    return out

