def match_order(book, incoming):
    buy = incoming['side'] == 'BUY'
    opposite = book['asks'] if buy else book['bids']
    crosses = (lambda r: r['price'] <= incoming['price']) if buy else (lambda r: r['price'] >= incoming['price'])
    remaining, trades = incoming['qty'], []
    while remaining and opposite and crosses(opposite[0]):
        resting = opposite[0]
        qty = min(remaining, resting['qty'])
        trades.append((resting['id'], resting['price'], qty))
        remaining -= qty
        resting['qty'] -= qty
        if resting['qty'] == 0:
            opposite.pop(0)
    if remaining:
        insert_order(book, dict(incoming, qty=remaining))
    return {'trades': trades, 'remaining': remaining}

def average_fill_price(trades):
    total_qty = sum(q for _, _, q in trades)
    if not total_qty:
        return 0.0
    return round(sum(p * q for _, p, q in trades) / total_qty, 4)

def twap_schedule(qty, duration_min, interval_min):
    n = duration_min // interval_min
    if n <= 0:
        raise ValueError('no slices')
    base, extra = divmod(qty, n)
    return [base + (1 if i < extra else 0) for i in range(n)]

