def run_matching(orders):
    book = {'bids': [], 'asks': []}
    trades = []
    for o in orders:
        trades += match_order(book, dict(o))
    return {
        'trades': len(trades),
        'volume': sum(q for _, _, q in trades),
        'best_bid': book['bids'][0]['price'] if book['bids'] else None,
        'best_ask': book['asks'][0]['price'] if book['asks'] else None,
    }

