def impact_cost(shares, rate, gamma, eta):
    permanent = 0.5 * gamma * shares ** 2
    temporary = eta * rate * shares
    return {'permanent': round(permanent, 4), 'temporary': round(temporary, 4), 'total': round(permanent + temporary, 4)}

def slippage_bps(decision_price, fill_price, side):
