def micro_price(bid, bid_qty, ask, ask_qty):
    total = bid_qty + ask_qty
    obi = (bid_qty - ask_qty) / total
    micro = (bid * ask_qty + ask * bid_qty) / total
    return {'obi': round(obi, 4), 'micro': round(micro, 4)}

def obi_signal(obi, threshold=0.3):
    obi = max(-1.0, min(1.0, obi))
    if obi >= threshold:
        signal = 'BUY_PRESSURE'
    elif obi <= -threshold:
        signal = 'SELL_PRESSURE'
    else:
        signal = 'NEUTRAL'
    return signal, round((obi + 1) / 2 * 100, 1)

def as_quotes(mid, inventory, gamma, sigma, t_left, half_spread):
