    return {'reservation': round(r, 4), 'bid': round(r - half_spread, 4), 'ask': round(r + half_spread, 4)}

def inventory_action(inventory, limit):
    if abs(inventory) >= limit:
        return 'STOP_BUYING' if inventory > 0 else 'STOP_SELLING'
    if abs(inventory) >= 0.8 * limit:
        return 'SKEW_QUOTES'
    return 'NORMAL'

def valid_fix_checksum(raw):
    i = raw.rfind('\x0110=')
    if i == -1:
        return False
    start = i + 1
    value = raw[start + 3:].rstrip('\x01')
    if not value.isdigit():
        return False
    return sum(ord(c) for c in raw[:start]) % 256 == int(value)

import struct


def parse_add_order(buf):
    if len(buf) != 26:
        raise ValueError('an add order is 26 bytes')
    kind, ref, side, shares, stock, price = struct.unpack('>cQcI8sI', buf)
    if kind != b'A':
        raise ValueError('not an add order')
    return {'ref': ref, 'side': 'BUY' if side == b'B' else 'SELL', 'shares': shares,
            'stock': stock.decode('ascii').strip(), 'price': price / 10000}

