class SpscQueue:
    def __init__(self, capacity):
        if capacity <= 0 or capacity & (capacity - 1):
            raise ValueError('capacity must be a power of two')
        self.capacity = capacity
        self.mask = capacity - 1
        self.slots = [None] * capacity
        self.head = 0
        self.tail = 0

    def enqueue(self, item):
        if self.head - self.tail == self.capacity:
            return False
        self.slots[self.head & self.mask] = item
        self.head += 1
        return True

    def dequeue(self):
        if self.head == self.tail:
            return None
        item = self.slots[self.tail & self.mask]
        self.tail += 1
        return item

    def size(self):
        return self.head - self.tail

def is_power_of_two(n):
    return n > 0 and n & (n - 1) == 0


def next_power_of_two(n):
    p = 1
    while p < n:
        p *= 2
    return p

def false_sharing(fields, line=64):
    def lines(f):
        return set(range(f['offset'] // line, (f['offset'] + f['size'] - 1) // line + 1))
    pairs = []
    for i in range(len(fields)):
        for j in range(i + 1, len(fields)):
            a, b = fields[i], fields[j]
            if a['thread'] != b['thread'] and lines(a) & lines(b):
                pairs.append(tuple(sorted((a['name'], b['name']))))
    return sorted(pairs)

def padding_bytes(size, line=64):
    return (-size) % line


def padded_size(size, line=64):
    return size + padding_bytes(size, line)

def simd_dot(a, b, width=8):
    full = len(a) // width * width
    total = 0.0
    for start in range(0, full, width):
        total += sum(x * y for x, y in zip(a[start:start + width], b[start:start + width]))
    total += sum(a[i] * b[i] for i in range(full, len(a)))
    return {'dot': round(total, 4), 'simd_steps': len(a) // width, 'tail_steps': len(a) % width}

def amdahl_speedup(width, parallel_fraction):
    p = parallel_fraction
    return round(1 / ((1 - p) + p / width), 2)

