def parity_gap(C, P, S, K, r, T, tolerance=0.05):
    gap = round((C - P) - (S - K * math.exp(-r * T)), 4)
    return {'gap': gap, 'status': 'OK' if abs(gap) <= tolerance else 'ARBITRAGE'}

import math


def implied_vol(price, S, K, T, r, guess=0.2, tol=1e-6, max_iter=50):
    N = lambda x: 0.5 * (1 + math.erf(x / math.sqrt(2)))
    n = lambda x: math.exp(-x * x / 2) / math.sqrt(2 * math.pi)

    def d1(sig):
        return (math.log(S / K) + (r + sig ** 2 / 2) * T) / (sig * math.sqrt(T))

    def bs_call(sig):
        a = d1(sig)
        return S * N(a) - K * math.exp(-r * T) * N(a - sig * math.sqrt(T))

    sigma = guess
    for _ in range(max_iter):
        if sigma <= 0:
            return None
        diff = bs_call(sigma) - price
        if abs(diff) < tol:
            return round(sigma, 4)
        vega = S * n(d1(sigma)) * math.sqrt(T)
        if vega < 1e-8:
            return None
        sigma -= diff / vega
    return None

import math


def bs_vega(S, K, T, r, sigma):
    d1 = (math.log(S / K) + (r + sigma ** 2 / 2) * T) / (sigma * math.sqrt(T))
    vega = S * math.exp(-d1 * d1 / 2) / math.sqrt(2 * math.pi) * math.sqrt(T)
    return round(vega, 4), round(vega / 100, 4)

Z = {0.95: 1.645, 0.99: 2.326}


def parametric_var(value, mean, vol, confidence=0.95):
    if confidence not in Z:
        raise ValueError('confidence must be 0.95 or 0.99')
    pct = Z[confidence] * vol - mean
    return {'var_pct': round(pct, 6), 'var_amount': round(value * pct, 2)}

