def historical_var(returns, value, confidence=0.95):
    s = sorted(returns)
    cut = s[int(math.floor((1 - confidence) * len(s) + 1e-9))]
    return round(value * -cut, 2)


def scale_var(one_day, days):
    return round(one_day * math.sqrt(days), 2)

def expected_shortfall(returns, confidence=0.95):
    k = max(1, round((1 - confidence) * len(returns)))
    tail = sorted(returns)[:k]
    return {'var': round(-tail[-1], 4), 'es': round(-sum(tail) / k, 4)}

def diversification(risk_a, risk_b, risk_combined):
    total = risk_a + risk_b
    benefit = round(total - risk_combined, 2)
    return {'subadditive': risk_combined <= total, 'benefit': benefit, 'benefit_pct': round(benefit / total * 100, 1)}

def min_variance_weight(sig_a, sig_b, rho):
    num = sig_b ** 2 - rho * sig_a * sig_b
    den = sig_a ** 2 + sig_b ** 2 - 2 * rho * sig_a * sig_b
    return round(num / den, 4)

def risk_engine(positions, pnl_scenarios, confidence=0.99):
    net_delta = sum(p['qty'] * p['delta'] for p in positions)
    net_vega = sum(p['qty'] * p['vega'] for p in positions)
    k = max(1, round((1 - confidence) * len(pnl_scenarios)))
    tail = sorted(pnl_scenarios)[:k]
    return {'net_delta': round(net_delta, 2), 'net_vega': round(net_vega, 2),
            'var': round(-tail[-1], 2), 'es': round(-sum(tail) / k, 2)}

def delta_hedge(net_delta, delta_per_unit=1.0):
    units = -round(net_delta / delta_per_unit)
    return units or 0

def pairs_signal(price_a, price_b, beta, mean, std, entry=2.0, exit_z=0.5):
    z = (price_a - beta * price_b - mean) / std
    if z >= entry:
        signal = 'SHORT_SPREAD'
    elif z <= -entry:
        signal = 'LONG_SPREAD'
    elif abs(z) <= exit_z:
        signal = 'EXIT'
    else:
        signal = 'HOLD'
    return {'z': round(z, 4), 'signal': signal}

