def half_life(theta):
    if theta <= 0:
        raise ValueError('no mean reversion')
    return round(math.log(2) / theta, 4)

def route_buy(qty, venues):
    left, fills, cost = qty, [], 0.0
    for v in sorted(venues, key=lambda v: (v['price'] + v['fee'], v['name'])):
        if left == 0:
            break
        take = min(left, v['size'])
        if take:
            fills.append((v['name'], take))
            cost += (v['price'] + v['fee']) * take
            left -= take
    filled = qty - left
    return {'fills': fills, 'unfilled': left, 'avg_cost': round(cost / filled, 4) if filled else 0.0}

def net_fee(shares, fee_per_share):
    amount = round(shares * fee_per_share, 2)
    kind = 'FEE' if amount > 0 else ('REBATE' if amount < 0 else 'NONE')
    return {'amount': amount, 'kind': kind}

C = 299_792_458


def fibre_latency(meters, n=1.4682):
    one_way = meters * n / C * 1e9
    return {'one_way_ns': round(one_way, 2), 'round_trip_ns': round(one_way * 2, 2)}

C = 299_792_458


def microwave_advantage(distance_km, fibre_route_factor=1.1):
    us = lambda meters, n: meters * n / C * 1e6
    fibre = us(distance_km * 1000 * fibre_route_factor, 1.4682)
    micro = us(distance_km * 1000, 1.0003)
    return {'fibre_us': round(fibre, 3), 'microwave_us': round(micro, 3), 'saved_us': round(fibre - micro, 3)}

def microwave_link(distance_km, towers, hop_ns, rain_mm_h, rain_limit=25.0):
    if rain_mm_h >= rain_limit:
        return {'latency_ns': None, 'status': 'DOWN'}
    prop = distance_km * 1000 * 1.0003 / 299_792_458 * 1e9
    status = 'UP' if rain_mm_h < rain_limit * 0.6 else 'DEGRADED'
    return {'latency_ns': round(prop + towers * hop_ns), 'status': status}

