import math


def haircut_sharpe(observed, trials, sr_std=0.5):
    if trials <= 1:
        return observed
    return round(observed - sr_std * math.sqrt(2 * math.log(trials)), 4)

def pre_trade_check(order, limits, mid):
    reasons = []
    if order['qty'] > limits['max_qty']:
        reasons.append('MAX_QTY')
    if order['qty'] * order['price'] > limits['max_notional']:
        reasons.append('MAX_NOTIONAL')
    if abs(order['price'] - mid) / mid * 100 > limits['collar_pct']:
        reasons.append('PRICE_COLLAR')
    return {'approved': not reasons, 'reasons': reasons}

def kill_switch_index(orders, daily_cap):
    total = 0.0
    for i, (qty, price) in enumerate(orders):
        total += qty * price
        if total > daily_cap:
            return i
    return None

def funding(notional, rate_8h_pct, periods, side='LONG'):
    amount = notional * rate_8h_pct / 100 * periods
    payment = -amount if side == 'LONG' else amount
    return {'payment': round(payment, 2) + 0.0, 'apr_pct': round(rate_8h_pct * 3 * 365, 2)}

def liquidation_price(entry, leverage, maintenance_pct=0.5, side='LONG'):
    m = maintenance_pct / 100
    if side == 'LONG':
        return round(entry * (1 - 1 / leverage + m), 2)
    return round(entry * (1 + 1 / leverage - m), 2)

def fpga_latency(stages, clock_mhz, cycles_per_stage=1):
    cycles = stages * cycles_per_stage
    return {'cycles': cycles, 'latency_ns': round(cycles / clock_mhz * 1000, 2),
            'max_msgs_per_sec': clock_mhz * 1_000_000 // cycles_per_stage}

def lut_utilization(used, total):
    pct = used / total * 100
    if pct > 100:
        status = 'DOES_NOT_FIT'
    elif pct > 90:
        status = 'RISKY'
    elif pct >= 70:
        status = 'TIGHT'
    else:
        status = 'OK'
    return {'pct': round(pct, 1), 'status': status}

def readiness(checks, p99_ns, budget_ns):
    failed = sorted(n for n, ok in checks.items() if not ok)
    if p99_ns > budget_ns:
        failed.append('LATENCY')
    return {'failed': failed, 'ready': bool(checks) and not failed}
